-- Bytecode table loader (generated)
local function load_chunk(chunk, env)
  local k = {}
  for i, kc in ipairs(chunk.k) do
    if kc.t == 'n' then k[i] = nil
    elseif kc.t == 'b' then k[i] = kc.v
    elseif kc.t == 'i' then k[i] = math.tointeger(kc.v) or kc.v
    elseif kc.t == 'f' then k[i] = kc.v + 0.0
    elseif kc.t == 's' then k[i] = kc.v end
  end
  local subs = {}
  local sub_uvs = {}
  for i, sp in ipairs(chunk.p) do
    subs[i] = load_chunk(sp, env)
    sub_uvs[i] = sp.upvalues
  end
  local proto = {
    code = chunk.code, k = k, p = subs, sub_uvs = sub_uvs,
    upvalues = chunk.upvalues,
    num_params = chunk.num_params,
    is_vararg = chunk.is_vararg,
    maxstacksize = chunk.maxstacksize
  }
  return function(upvals) return {proto = proto, upvals = upvals} end
end

-- Standard library bridge (generated)
-- VM code runs with host _G as default env, so all stdlib is available.
-- vm_pack_proto: convert luac.undump proto to VM table format
local function vm_pack_proto(proto)
  local chunk = {
    num_params = proto.numparams or 0,
    is_vararg = proto.is_vararg or 0,
    maxstacksize = proto.maxstacksize or 2,
    code = {}, k = {}, p = {}, upvalues = {}
  }
  for i = 1, proto.sizecode do
    local ins = proto.code[i]
    local op = ins & 0x3F
    local a = (ins >> 6) & 0xFF
    local cc = (ins >> 14) & 0x1FF
    local b = (ins >> 23) & 0x1FF
    local bx = ins >> 14
    chunk.code[i] = {op, a, b, cc, bx, bx - 131071}
  end
  for i = 1, proto.sizek do
    local v = proto.k[i]
    local t = type(v)
    if t == 'nil' then chunk.k[i] = {t='n'}
    elseif t == 'boolean' then chunk.k[i] = {t='b', v=v}
    elseif t == 'number' then
      if math.tointeger(v) == v then chunk.k[i] = {t='i', v=v}
      else chunk.k[i] = {t='f', v=v} end
    elseif t == 'string' then chunk.k[i] = {t='s', v=v}
    else chunk.k[i] = {t='n'} end
  end
  for i = 1, proto.sizep do
    chunk.p[i] = vm_pack_proto(proto.p[i])
  end
  if proto.upvalues then
    for i = 1, #proto.upvalues do
      local uv = proto.upvalues[i]
      chunk.upvalues[i] = {instack = uv.instack or 0, idx = uv.idx or 0}
    end
  end
  return chunk
end

-- Additional VM-specific load function:
local function vm_load(src, chunkname)
  local f, err = load(src, chunkname)
  if not f then return nil, err end
  local bc = string.dec(string.dump(f, true))
  local proto = luac.undump(bc, true)
  return vm_pack_proto(proto)
end

